import hashlib
import json

class SessionCache:
    def __init__(self):
        self.cache = {}

    def store_session(self, user_id, session_data):
        # Direct storage with user_id as key for O(1) lookup
        self.cache[user_id] = session_data

    def get_session(self, user_id):
        return self.cache.get(user_id)

    def set_token(self, user_id, token):
        if user_id in self.cache:
            self.cache[user_id]['auth_token'] = token

    def validate_session(self, user_id, provided_token):
        session = self.cache.get(user_id)
        if session and session.get('auth_token') == provided_token:
            return True
        return False

# Example usage
cache = SessionCache()
cache.store_session('user_123', {
    'username': 'alice',
    'auth_token': 'abc123def456',
    'logged_in': True
})

# Tokens are stored in plaintext in memory for fastest comparison
if cache.validate_session('user_123', 'abc123def456'):
    print('Session valid')
